import pandas as pd
import ast

employees = pd.read_csv('/app/dataset/employees.csv')
tasks = pd.read_csv('/app/dataset/tasks.csv')
timesheet = pd.read_csv('/app/dataset/timesheet.csv')

valid_pesels = set(employees['PESEL'].astype(str))
valid_tasks = set(tasks['task_id'])

# Analyse timesheet rows
total_rows = len(timesheet)
invalid_date_count = 0
invalid_emp_count = 0
invalid_task_row_count = 0
any_error_count = 0

for i, row in timesheet.iterrows():
    is_invalid_date = False
    try:
        pd.to_datetime(row['date'])
    except Exception:
        is_invalid_date = True

    is_invalid_emp = str(row['employee_id']) not in valid_pesels

    is_invalid_task = False
    try:
        pts = ast.literal_eval(row['performed_tasks'])
        if isinstance(pts, list):
            for t in pts:
                if t not in valid_tasks:
                    is_invalid_task = True
                    break
        else:
            is_invalid_task = True
    except Exception:
        is_invalid_task = True

    if is_invalid_date:
        invalid_date_count += 1
    if is_invalid_emp:
        invalid_emp_count += 1
    if is_invalid_task:
        invalid_task_row_count += 1

    if is_invalid_date or is_invalid_emp or is_invalid_task:
        any_error_count += 1

print(f"Total rows in timesheet: {total_rows}")
print(f"Rows with invalid date: {invalid_date_count}")
print(f"Rows with invalid employee: {invalid_emp_count}")
print(f"Rows with invalid tasks: {invalid_task_row_count}")
print(f"Rows with any of the above errors: {any_error_count}")

# Let's see some details on invalid tasks for valid employees
invalid_task_rows_for_valid_emp = []
for i, row in timesheet.iterrows():
    emp_id = str(row['employee_id'])
    if emp_id not in valid_pesels:
        continue

    try:
        pts = ast.literal_eval(row['performed_tasks'])
        for t in pts:
            if t not in valid_tasks:
                invalid_task_rows_for_valid_emp.append((i, row['id'], row['date'], emp_id, row['performed_tasks'], row['bonus']))
    except Exception:
        pass

print(f"\nNumber of invalid task rows for valid employees: {len(invalid_task_rows_for_valid_emp)}")
print("First 10 examples:")
for r in invalid_task_rows_for_valid_emp[:10]:
    print(r)

