import pandas as pd
import ast
from decimal import Decimal, ROUND_HALF_UP

employees = pd.read_csv('/app/dataset/employees.csv')
tasks = pd.read_csv('/app/dataset/tasks.csv')
timesheet = pd.read_csv('/app/dataset/timesheet.csv')

valid_pesels = set(employees['PESEL'].astype(str))
valid_tasks = set(tasks['task_id'])
task_pay = dict(zip(tasks['task_id'], tasks['pay_per_completion']))
emp_rate = dict(zip(employees['PESEL'].astype(str), employees['hourly_rate']))

def std_round(val):
    return int(Decimal(str(val)).to_integral_value(rounding=ROUND_HALF_UP))

def get_billing_month(dt_str, correct_date=False):
    if correct_date:
        if dt_str == '2025-04-31':
            dt_str = '2025-04-30'
        elif dt_str == '2025-06-31':
            dt_str = '2025-06-30'

    try:
        dt = pd.to_datetime(dt_str)
    except Exception:
        return None

    if pd.Timestamp('2025-03-04') <= dt <= pd.Timestamp('2025-03-31'):
        return '2025-03'
    elif pd.Timestamp('2025-04-01') <= dt <= pd.Timestamp('2025-05-05'):
        return '2025-04'
    elif pd.Timestamp('2025-05-06') <= dt <= pd.Timestamp('2025-06-02'):
        return '2025-05'
    elif pd.Timestamp('2025-06-03') <= dt <= pd.Timestamp('2025-06-30'):
        return '2025-06'
    else:
        return None

def run_strategy(dedup, correct_date, exclude_row_on_invalid_task):
    months = ['2025-03', '2025-04', '2025-05', '2025-06']
    salaries = {pesel: {m: {'hours': 0.0, 'bonus': 0.0} for m in months} for pesel in valid_pesels}

    df = timesheet.copy()

    # 1. Deduplicate if requested
    if dedup:
        cols_to_check = ['date', 'hours_worked', 'performed_tasks', 'employee_id', 'facility_id', 'salary_amount', 'bonus']
        df = df.drop_duplicates(subset=cols_to_check)

    for idx, row in df.iterrows():
        emp_id = str(row['employee_id'])
        if emp_id not in valid_pesels:
            continue

        b_month = get_billing_month(row['date'], correct_date=correct_date)
        if b_month is None:
            continue

        try:
            pts = ast.literal_eval(row['performed_tasks'])
        except Exception:
            pts = []

        # Check invalid tasks
        has_invalid_task = any(t not in valid_tasks for t in pts)
        if exclude_row_on_invalid_task and has_invalid_task:
            continue

        # Ignore negative bonus (since those are highly inconsistent rows with 0 hours worked)
        if row['bonus'] < 0:
            continue

        # Sum valid task pays
        bonus_val = sum(task_pay[t] for t in pts if t in valid_tasks)

        salaries[emp_id][b_month]['hours'] += row['hours_worked']
        salaries[emp_id][b_month]['bonus'] += bonus_val

    result = {}
    for pesel in sorted(valid_pesels):
        rate = emp_rate[pesel]
        emp_salaries = []
        for m in months:
            hours = salaries[pesel][m]['hours']
            bonus = salaries[pesel][m]['bonus']
            total = hours * rate + bonus
            emp_salaries.append(std_round(total))
        result[pesel] = emp_salaries

    return result

# Run combinations
combinations = [
    ("No-Dedup, Excl-Date, Excl-Task-Row", False, False, True),
    ("No-Dedup, Excl-Date, Keep-Task-Row", False, False, False),
    ("No-Dedup, Corr-Date, Keep-Task-Row", False, True, False),

    ("Dedup, Excl-Date, Excl-Task-Row", True, False, True),
    ("Dedup, Excl-Date, Keep-Task-Row", True, False, False),
    ("Dedup, Corr-Date, Keep-Task-Row", True, True, False),
]

for name, dedup, corr, excl_task in combinations:
    res = run_strategy(dedup, corr, excl_task)
    # let's print the salary of one employee
    emp = '68011810139'
    print(f"{name:<40} -> {emp}: {res[emp]}")

